<script setup lang="ts">
import { ref,onMounted } from 'vue'
import { api,label } from './api'
import EvidenceNode from './EvidenceNode.vue'
const props=defineProps<{scan:string,node:number}>(),emit=defineEmits(['source'])
const page=ref<any>(null),rows=ref<any[]>([]),busy=ref(false),error=ref('')
const read=async(node:number)=>{const n=await api('/scans/'+props.scan+'/nodes/'+node+'?limit=200');return n.items||[]}
async function load(offset=0){busy.value=true;try{page.value=await api('/scans/'+props.scan+'/nodes/'+props.node+'?limit=10&offset='+offset);const next=[];for(const row of page.value.items){const fields=await read(row.id),value:any={node:row.id};for(const field of fields){if(field.kind!=='object'&&field.kind!=='list')value[field.key]=field.value;else if(['participant_a','participant_b'].includes(field.key)){const part=await read(field.id);value[field.key]=Object.fromEntries(part.filter((x:any)=>x.kind!=='object'&&x.kind!=='list').map((x:any)=>[x.key,x.value]))}}next.push(value)}rows.value=next}catch(e:any){error.value=e.message}finally{busy.value=false}}
onMounted(()=>load())
</script>
<template><section class="conflict-pairs"><h4>潜在并发关系 · {{page?.total || 0}} 组</h4><p class="muted">根据归档证据推断的潜在交错，未经目标板采集；完整路径、成立条件与不确定性保留在每组证据中。</p><p v-if="busy">正在读取关系…</p><p v-if="error" class="banner error">{{error}}</p><article v-for="(row,index) in rows" :key="row.node" class="conflict-pair"><strong>关系 {{(page?.offset||0)+index+1}} · {{row.may_concurrent===true?'可能并发':row.may_concurrent===false?'此关系未证明并发':'并发条件待核实'}}</strong><div class="context-lanes"><div v-for="key in ['participant_a','participant_b']" :key="key"><template v-if="row[key]"><strong>{{row[key].context_id || '上下文待核实'}}</strong><p>{{label(row[key].access_kind)}} · {{row[key].function_id}}</p><button v-if="row[key].file" @click="emit('source',{file:row[key].file,line:row[key].line||1})">{{row[key].file}}:{{row[key].line}} · 定位代码</button></template><p v-else>采用压缩关系表示，展开下方读取完整上下文选择器和全部参与访问。</p></div></div><EvidenceNode :scan="scan" :node="row.node" title="本组全部路径引用、保护与成立条件"/></article><p v-if="page?.total===0">此变量没有已构造的并发关系；这不构成安全证明，请核对覆盖缺口和调用入口。</p><div v-if="page?.total>10" class="page-controls"><button :disabled="busy||!page.offset" @click="load(Math.max(0,page.offset-10))">前10组关系</button><span>显示 {{page.offset+1}}–{{page.offset+rows.length}} / {{page.total}}</span><button :disabled="busy||page.next_offset===null" @click="load(page.next_offset)">后10组关系</button></div></section></template>
